const DEPTH_MAX = 3;
function bodyOf(frame) {
    try {
        return frame.contentDocument?.body ?? null;
    }
    catch {
        return null;
    }
}
export function sameOriginFrameBodies(root) {
    const found = [];
    const walk = (node, depth) => {
        if (depth >= DEPTH_MAX)
            return;
        for (const frame of node.querySelectorAll('iframe')) {
            const body = bodyOf(frame);
            if (null === body)
                continue;
            found.push(body);
            walk(body, depth + 1);
        }
    };
    walk(root, 0);
    return found;
}
export function observeSameOriginFrames(attach) {
    const attachAll = () => {
        for (const body of sameOriginFrameBodies(document))
            attach(body);
    };
    attachAll();
    const onLoad = (event) => {
        if (event.target instanceof HTMLIFrameElement)
            attachAll();
    };
    document.addEventListener('load', onLoad, true);
    return () => {
        document.removeEventListener('load', onLoad, true);
    };
}
